#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<long long> degree(n + 1, 0);
    for (const vector<long long>& e : edges) {
        degree[e[0]]++;
        degree[e[1]]++;
    }
    for (int v = 1; v <= n; v++) cout << (v > 1 ? " " : "") << degree[v];
    cout << "\n";

    return 0;
}

